@PostMapping("/probe/createTask")
public Result createTask(@RequestBody TaskRequest req) {
  // 无 @PreAuthorize，无全局拦截器，无身份校验
  taskService.create(req); // 任意调用者可创建任意任务记录
  return Result.ok();
}

@PreAuthorize("hasRole('ADMIN')")
@PostMapping("/probe/createTask")
public Result createTask(@RequestBody TaskRequest req) {
  taskService.create(req); // 鉴权已校验
  return Result.ok();
}

@GetMapping("/task/autoAssign")
public Result autoAssignTask(@PathVariable String taskId) {
  // 无 @PreAuthorize，无全局拦截器
  Task t = taskDao.selectById(taskId); // 只读，无写库/SQL拼接/命令/SSRF落地
  return Result.ok(suggestAssign(t)); // 返回派工建议，不落库不改数据
}

@PostMapping("/msg/retry")
public Result retry(@RequestBody SubPolicyReq req) {
  // 无 @PreAuthorize
  subPolicyComponent.createSubPolicy(req); // 仅 sendSubPolicyMsg/sendSubjectMsg → DMS（仓外 consumer），本仓无 proposalRespository.persist
  return Result.ok();
}

// zeus-facade-service.xml: <sofa:service interface="FooService" ref="fooServiceImpl"><sofa:binding.bolt/></sofa:service>
@GetMapping("/foo/change")
public Result change(@PathVariable String id) { // 公网 HTTP 端点,无 @PreAuthorize
  fooServiceImpl.change(id); // 经公网可达该 RPC facade → 缺失鉴权构成 CWE-862
  return Result.ok();
}

// zeus-facade-service.xml: <sofa:service interface="FooService" ref="fooServiceImpl"><sofa:binding.bolt/></sofa:service>
// FooServiceImpl::change 仅被其他 ServiceImpl 经 RPC 调,无 @Controller 调者
public void change(String id) { fooDao.update(id); } // 无公网入口 → 非 CWE-862
